function issueCsrfToken(req) { if (!req.session.csrfToken) req.session.csrfToken = crypto.randomBytes(32).toString('base64url'); return req.session.csrfToken; }
app.get('/api/auth/csrf', (req, res, next) => { try { const csrfToken = issueCsrfToken(req); return req.session.save((error) => error ? next(error) : res.json({ csrfToken })); } catch (error) { return next(error); } });
app.use('/api', (req, res, next) => {
  const unsafe = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method); const webhook = req.path === '/webhooks/whatsapp' || req.path === '/webhooks/sms';
  if (!unsafe || webhook) return next(); const expected = req.session?.csrfToken; const supplied = req.get('x-csrf-token');
  const valid = expected && supplied && Buffer.byteLength(expected) === Buffer.byteLength(supplied) && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(supplied));
  return valid ? next() : next(new ApiError(403, 'Your secure session token is missing or expired. Refresh the page and try again.', 'CSRF_INVALID'));
});
