async function getUserById(id) { return db.one('SELECT * FROM users WHERE id = ? AND active = TRUE', id); }
function establishSession(req, user) { const csrfToken = req.session?.csrfToken || crypto.randomBytes(32).toString('base64url'); return new Promise<void>((resolve, reject) => req.session.regenerate((error) => { if (error) return reject(error); req.session.userId = user.id; req.session.csrfToken = csrfToken; req.session.authenticatedAt = nowIso(); req.session.mfaSatisfiedAt = nowIso(); return req.session.save((saveError) => saveError ? reject(saveError) : resolve()); })); }
function establishPreMfaSession(req, user) { const csrfToken = req.session?.csrfToken || crypto.randomBytes(32).toString('base64url'); return new Promise<void>((resolve, reject) => req.session.regenerate((error) => { if (error) return reject(error); req.session.preMfaUserId = user.id; req.session.preMfaStartedAt = nowIso(); req.session.csrfToken = csrfToken; return req.session.save((saveError) => saveError ? reject(saveError) : resolve()); })); }
async function preMfaUser(req) { const startedAt = req.session?.preMfaStartedAt ? new Date(req.session.preMfaStartedAt).getTime() : 0; if (!req.session?.preMfaUserId || !startedAt || Date.now() - startedAt > 15 * 60 * 1000) return null; return getUserById(req.session.preMfaUserId); }
async function requireAuth(req, res, next) { try { const user = req.session?.userId ? await getUserById(req.session.userId) : null; if (!user) return next(new ApiError(401, 'Please sign in to continue.', 'AUTH_REQUIRED')); req.user = { ...safeUser(user), _row: user }; return next(); } catch (error) { return next(error); } }
async function requireMfaSetup(req, res, next) { try { const user = req.session?.userId ? await getUserById(req.session.userId) : await preMfaUser(req); if (!user) return next(new ApiError(401, 'Start with your invitation or sign in before configuring MFA.', 'MFA_SETUP_AUTH_REQUIRED')); req.user = { ...safeUser(user), _row: user }; return next(); } catch (error) { return next(error); } }
function requireRoles(...roles) { return (req, res, next) => !req.user || !roles.includes(req.user.role) ? next(new ApiError(403, 'You do not have permission to perform this action.', 'FORBIDDEN')) : next(); }
function canRevealPhone(user) { return ['owner', 'membership_officer'].includes(user.role); }
function canViewMember(user, member) { if (['owner', 'membership_officer'].includes(user.role)) return true; if (user.role === 'birthday_coordinator') return user.groupScope.length === 0 || user.groupScope.includes(member.ministry_group); return false; }
function applicationBaseUrl(req) { return (process.env.APP_ORIGIN || process.env.RENDER_EXTERNAL_URL || `${req.protocol}://${req.get('host')}`).replace(/\/$/, ''); }
function webAuthnConfiguration(req) { const origin = process.env.WEBAUTHN_ORIGIN || applicationBaseUrl(req); let parsed; try { parsed = new URL(origin); } catch { throw new ApiError(503, 'The passkey origin is not configured correctly.', 'PASSKEY_CONFIGURATION_ERROR'); } const rpID = process.env.WEBAUTHN_RP_ID || parsed.hostname; if (isProduction && (!process.env.WEBAUTHN_ORIGIN || !process.env.WEBAUTHN_RP_ID)) throw new ApiError(503, 'Passkeys are not ready yet. Configure WEBAUTHN_ORIGIN and WEBAUTHN_RP_ID in Render first.', 'PASSKEY_CONFIGURATION_REQUIRED'); if (isProduction && parsed.protocol !== 'https:') throw new ApiError(503, 'Passkeys require an HTTPS application origin.', 'PASSKEY_HTTPS_REQUIRED'); return { origin, rpID }; }
function cleanString(value, fallback = '') { return typeof value === 'string' ? value.trim() : fallback; }
function normalizePhone(value) { const parsed = parsePhoneNumberFromString(String(value || '').trim(), 'NG'); if (!parsed || !parsed.isValid()) throw new ApiError(422, 'Enter a valid mobile number. Nigerian numbers may be entered as 080… or +234….', 'INVALID_PHONE'); return parsed.number; }
function assertDate(month, day) { if (!isValidMonthDay(month, day)) throw new ApiError(422, 'The birthday month and day do not form a valid calendar date.', 'INVALID_BIRTHDAY'); }
function birthdayMatchesDate(member, date, feb29Policy) { if (Number(member.birth_month) === date.month && Number(member.birth_day) === date.day) return true; if (Number(member.birth_month) !== 2 || Number(member.birth_day) !== 29) return false; const leap = date.year % 4 === 0 && (date.year % 100 !== 0 || date.year % 400 === 0); return leap ? date.month === 2 && date.day === 29 : feb29Policy === 'mar1' ? date.month === 3 && date.day === 1 : date.month === 2 && date.day === 28; }
function datePartsFromIso(value) { if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ''))) return null; const [year, month, day] = value.split('-').map(Number); const date = new Date(Date.UTC(year, month - 1, day)); return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day ? { year, month, day } : null; }

const memberSchema = z.object({ firstName: z.string().trim().min(2).max(80), lastName: z.string().trim().min(2).max(80), preferredName: z.string().trim().max(80).nullable().optional(), phone: z.string().trim().min(7).max(40), birthMonth: z.coerce.number().int().min(1).max(12), birthDay: z.coerce.number().int().min(1).max(31), birthYear: z.union([z.coerce.number().int().min(1900).max(new Date().getFullYear()), z.null()]).optional(), status: z.enum(['active','visitor','inactive','archived','deceased']).default('active'), ministryGroup: z.string().trim().min(2).max(80).default('General'), birthdayAlertAllowed: z.boolean().default(true), consentRecorded: z.boolean().default(false), confirmPotentialDuplicate: z.boolean().optional().default(false) });
function parseMemberPayload(payload, { requireConsent = false } = {}) { const result = memberSchema.safeParse(payload); if (!result.success) throw new ApiError(422, 'Please correct the highlighted member details.', 'INVALID_MEMBER', result.error.issues.map((issue) => ({ path: issue.path.join('.'), message: issue.message }))); const data = result.data; assertDate(data.birthMonth, data.birthDay); if (requireConsent && !data.consentRecorded) throw new ApiError(422, 'Record the applicable membership/privacy basis before saving this person.', 'CONSENT_REQUIRED'); return { ...data, preferredName: data.preferredName || null, phone: normalizePhone(data.phone), birthYear: data.birthYear || null }; }
async function nextMemberCode() { const row = await db.one("SELECT nextval('member_code_sequence')::int AS number"); return `LW-${String(row.number)}`; }
async function memberDuplicate(phoneHash, ignoreId = null) { return ignoreId ? db.one('SELECT * FROM members WHERE phone_hash = ? AND id != ?', phoneHash, ignoreId) : db.one('SELECT * FROM members WHERE phone_hash = ?', phoneHash); }
function makeMember(row, user) { return memberDto(row, { revealPhone: canRevealPhone(user) }); }
async function createMember(data, user, { source = 'Member form' } = {}) { const phoneHash = lookupHash(data.phone); const duplicate = await memberDuplicate(phoneHash); if (duplicate && !data.confirmPotentialDuplicate) throw new ApiError(409, 'A record with this phone number may already exist. Review it before creating a duplicate.', 'DUPLICATE_CANDIDATE', { existing: memberDto(duplicate, { revealPhone: false }) }); const id = newId('mem_'); const timestamp = nowIso(); const code = await nextMemberCode(); await db.transaction(async (tx) => { await tx.run(`INSERT INTO members (id, member_code, first_name, last_name, preferred_name, phone_encrypted, phone_hash, birth_month, birth_day, birth_year, status, ministry_group, birthday_alert_allowed, consent_status, consent_at, privacy_notice_version, created_at, created_by, updated_at, updated_by, archived_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'recorded', ?, 'v1.0', ?, ?, ?, ?, ?)`, id, code, data.firstName, data.lastName, data.preferredName, encryptValue(data.phone), phoneHash, data.birthMonth, data.birthDay, data.birthYear, data.status, data.ministryGroup, data.birthdayAlertAllowed, timestamp, timestamp, user.id, timestamp, user.id, data.status === 'archived' ? timestamp : null); await tx.run(`INSERT INTO consent_records (id, member_id, purpose, lawful_basis, action, source, notice_version, recorded_at, recorded_by, details) VALUES (?, ?, 'Membership care and birthday reminders', 'Recorded church membership purpose', 'recorded', ?, 'v1.0', ?, ?, ?)`, newId('consent_'), id, source, timestamp, user.id, 'Recorded during membership intake.'); }); await audit({ actorId: user.id, actorName: user.fullName, action: 'member_created', entityType: 'member', entityId: id, summary: `Created member record ${code}.` }); return makeMember(await db.one('SELECT * FROM members WHERE id = ?', id), user); }
async function updateMember(id, data, user) { const existing = await db.one('SELECT * FROM members WHERE id = ?', id); if (!existing) throw new ApiError(404, 'Member not found.', 'MEMBER_NOT_FOUND'); const phoneHash = lookupHash(data.phone); const duplicate = await memberDuplicate(phoneHash, id); if (duplicate && !data.confirmPotentialDuplicate) throw new ApiError(409, 'A record with this phone number may already exist. Review it before saving.', 'DUPLICATE_CANDIDATE', { existing: memberDto(duplicate, { revealPhone: false }) }); const timestamp = nowIso(); await db.run(`UPDATE members SET first_name = ?, last_name = ?, preferred_name = ?, phone_encrypted = ?, phone_hash = ?, birth_month = ?, birth_day = ?, birth_year = ?, status = ?, ministry_group = ?, birthday_alert_allowed = ?, updated_at = ?, updated_by = ?, archived_at = ? WHERE id = ?`, data.firstName, data.lastName, data.preferredName, encryptValue(data.phone), phoneHash, data.birthMonth, data.birthDay, data.birthYear, data.status, data.ministryGroup, data.birthdayAlertAllowed, timestamp, user.id, data.status === 'archived' ? (existing.archived_at || timestamp) : null, id); await audit({ actorId: user.id, actorName: user.fullName, action: 'member_updated', entityType: 'member', entityId: id, summary: `Updated member record ${existing.member_code}.` }); return makeMember(await db.one('SELECT * FROM members WHERE id = ?', id), user); }

async function allowedBirthdayMembers(user, days = 14) { const rule = await getNotificationRuleDto(); const rows = await db.all(`SELECT * FROM members WHERE status = 'active' AND birthday_alert_allowed = TRUE AND consent_status != 'withdrawn'`); const matching = []; for (let offset = 0; offset <= days; offset += 1) { const date = daysFromLagosToday(offset); for (const row of rows) if (birthdayMatchesDate(row, date, rule?.feb29Policy || 'feb28') && canViewMember(user, row)) matching.push({ ...memberDto(row, { revealPhone: false }), occurrenceDate: toIsoDate(date), daysUntil: offset }); } return matching.sort((a, b) => a.daysUntil - b.daysUntil || a.fullName.localeCompare(b.fullName)); }
function notificationDto(row) { return { id: row.id, notificationKey: row.notification_key, userId: row.user_id, recipientName: row.recipient_name || 'Administrator', endpointLabel: row.endpoint_label || 'Notification endpoint', endpointMasked: row.phone_encrypted ? `•••• ${String(decryptValue(row.phone_encrypted) || '').slice(-4)}` : null, channel: row.channel, type: row.notification_type, scheduledFor: row.scheduled_for, messagePreview: row.message_preview, memberCount: Number(row.member_count), status: row.status, provider: row.provider, providerMessageId: row.provider_message_id, attempts: Number(row.attempts), errorCode: row.error_code, errorMessage: row.error_message, createdAt: row.created_at, sentAt: row.sent_at, deliveredAt: row.delivered_at, readAt: row.read_at, lastEventAt: row.last_event_at }; }
async function getNotifications(user, limit: string | number = 40) { const safeLimit = Math.min(Math.max(Number(limit) || 40, 1), 100); const query = `SELECT n.*, u.full_name AS recipient_name, endpoint.label AS endpoint_label, endpoint.phone_encrypted FROM notifications n INNER JOIN users u ON u.id = n.user_id INNER JOIN admin_endpoints endpoint ON endpoint.id = n.endpoint_id ${user.role === 'owner' ? '' : 'WHERE n.user_id = ?'} ORDER BY n.created_at DESC LIMIT ?`; const rows = user.role === 'owner' ? await db.all(query, safeLimit) : await db.all(query, user.id, safeLimit); return rows.map(notificationDto); }
async function dashboardFor(user) { const today = lagosDateParts(); const todayIso = toIsoDate(today); const [upcoming, activeRow, health, delivery, parish] = await Promise.all([allowedBirthdayMembers(user, 14), db.one(`SELECT COUNT(*)::int AS count FROM members WHERE status = 'active'`), db.one(`SELECT COUNT(*) FILTER (WHERE phone_encrypted IS NULL OR consent_status = 'review_required')::int AS issues FROM members WHERE status = 'active'`), user.role === 'owner' ? db.one(`SELECT COUNT(*)::int AS total, COUNT(*) FILTER (WHERE status IN ('delivered','read'))::int AS delivered, COUNT(*) FILTER (WHERE status IN ('failed','dead_letter'))::int AS failed FROM notifications WHERE created_at >= ?`, new Date(Date.now() - 30 * 86400000).toISOString()) : db.one(`SELECT COUNT(*)::int AS total, COUNT(*) FILTER (WHERE status IN ('delivered','read'))::int AS delivered, COUNT(*) FILTER (WHERE status IN ('failed','dead_letter'))::int AS failed FROM notifications WHERE user_id = ? AND created_at >= ?`, user.id, new Date(Date.now() - 30 * 86400000).toISOString()), db.one(`SELECT setting_value FROM app_settings WHERE setting_key = 'parish_profile'`)]); const total = Number(delivery.total || 0); return { date: todayIso, parish: JSON.parse(parish?.setting_value || '{}'), rule: await getNotificationRuleDto(), stats: { activeMembers: Number(activeRow.count || 0), todaysBirthdays: upcoming.filter((item) => item.daysUntil === 0).length, nextSevenDays: upcoming.filter((item) => item.daysUntil <= 7).length, deliveryRate: total ? Math.round(Number(delivery.delivered || 0) / total * 100) : null, failedDeliveries: Number(delivery.failed || 0), dataHealthIssues: Number(health.issues || 0) }, todaysBirthdays: upcoming.filter((item) => item.daysUntil === 0), upcoming: upcoming.slice(0, 7), recentNotifications: await getNotifications(user, 5) }; }
function verifyMetaSignature(req) { if (!WEBHOOK_APP_SECRET) return !isProduction; const signature = req.get('x-hub-signature-256'); if (!signature?.startsWith('sha256=')) return false; const expected = `sha256=${crypto.createHmac('sha256', WEBHOOK_APP_SECRET).update(req.rawBody || Buffer.from('')).digest('hex')}`; const provided = Buffer.from(signature); const actual = Buffer.from(expected); return provided.length === actual.length && crypto.timingSafeEqual(provided, actual); }
function verifyTermiiSignature(req) { const secret = process.env.TERMII_WEBHOOK_SECRET; const signature = req.get('x-termii-signature'); if (!secret) return !isProduction; if (!signature || !/^[a-f0-9]{128}$/i.test(signature)) return false; const expected = crypto.createHmac('sha512', secret).update(req.rawBody || Buffer.from('')).digest('hex'); const provided = Buffer.from(signature.toLowerCase(), 'hex'); const actual = Buffer.from(expected, 'hex'); return provided.length === actual.length && crypto.timingSafeEqual(provided, actual); }
function parseBirthdayString(value) { const raw = String(value || '').trim(); if (!raw) return null; const iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/); const ddMm = raw.match(/^(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{4}))?$/); return iso ? { year: Number(iso[1]), month: Number(iso[2]), day: Number(iso[3]) } : ddMm ? { day: Number(ddMm[1]), month: Number(ddMm[2]), year: ddMm[3] ? Number(ddMm[3]) : null } : null; }
function getField(row, ...names) { for (const name of names) { const hit = Object.keys(row).find((key) => key.toLowerCase().replace(/[ _-]/g, '') === name.toLowerCase().replace(/[ _-]/g, '')); if (hit && row[hit] !== undefined) return row[hit]; } return undefined; }
function unsafeCsvCell(value) { return /^[=+\-@]/.test(String(value || '').trim()); }
async function parseImportRows(csvText) { if (typeof csvText !== 'string' || csvText.length < 5 || csvText.length > 450000) throw new ApiError(422, 'Upload a CSV text file smaller than 450 KB.', 'INVALID_IMPORT'); let rows; try { rows = parseCsv(csvText, { columns: true, skip_empty_lines: true, relax_column_count: false, trim: true, bom: true }); } catch { throw new ApiError(422, 'The CSV could not be read. Include a header row and consistent columns.', 'INVALID_IMPORT'); } if (!rows.length || rows.length > 500) throw new ApiError(422, 'Import between 1 and 500 rows at a time.', 'INVALID_IMPORT'); const seen = new Set(); const results = []; for (let index = 0; index < rows.length; index += 1) { const row = rows[index]; const errors = []; if (Object.values(row).some(unsafeCsvCell)) errors.push('Formula-like values are not allowed.'); const firstName = cleanString(getField(row, 'first_name', 'firstname', 'first name')); const lastName = cleanString(getField(row, 'last_name', 'lastname', 'last name')); const phone = cleanString(getField(row, 'phone', 'mobile', 'phone_number')); const group = cleanString(getField(row, 'ministry_group', 'group', 'ministry')) || 'General'; const birthday = parseBirthdayString(getField(row, 'birthday', 'date_of_birth', 'dob')); const birthMonthRaw = getField(row, 'birth_month', 'month'); const birthDayRaw = getField(row, 'birth_day', 'day'); const birthYearRaw = getField(row, 'birth_year', 'year'); const birthMonth = birthday?.month || (birthMonthRaw !== undefined && String(birthMonthRaw).trim() !== '' ? Number(birthMonthRaw) : null); const birthDay = birthday?.day || (birthDayRaw !== undefined && String(birthDayRaw).trim() !== '' ? Number(birthDayRaw) : null); const birthYear = birthday?.year || (birthYearRaw !== undefined && String(birthYearRaw).trim() !== '' ? Number(birthYearRaw) : null); if (firstName.length < 2) errors.push('First name is required.'); if (lastName.length < 2) errors.push('Last name is required.'); let normalizedPhone; try { normalizedPhone = normalizePhone(phone); } catch { errors.push('Valid mobile phone is required.'); } if (!isValidMonthDay(birthMonth, birthDay)) errors.push('A valid birthday month/day or birthday date is required.'); if (birthYear && (birthYear < 1900 || birthYear > new Date().getFullYear())) errors.push('Birth year is outside the accepted range.'); const duplicate = normalizedPhone ? await memberDuplicate(lookupHash(normalizedPhone)) : null; const inFileDuplicate = normalizedPhone && seen.has(normalizedPhone); if (normalizedPhone) seen.add(normalizedPhone); if (inFileDuplicate) errors.push('Duplicate phone number within this upload.'); results.push({ rowNumber: index + 2, firstName, lastName, preferredName: cleanString(getField(row, 'preferred_name', 'preferredname')) || null, phone: normalizedPhone, birthMonth, birthDay, birthYear, ministryGroup: group, status: 'active', birthdayAlertAllowed: true, valid: errors.length === 0, errors, duplicate: duplicate ? { memberCode: duplicate.member_code, fullName: `${duplicate.first_name} ${duplicate.last_name}` } : null }); } return results; }

