app.post('/api/auth/login', loginLimiter, async (req, res, next) => { try { const parsed = z.object({ email: z.string().email(), password: z.string().min(1) }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Enter your email address and password.', 'INVALID_LOGIN'); const user = await db.one('SELECT * FROM users WHERE email = ? AND active = TRUE', parsed.data.email.toLowerCase().trim()); const passwordMatches = user ? await bcrypt.compare(parsed.data.password, user.password_hash) : false; if (!user || !passwordMatches) { await audit({ actorName: 'Anonymous', action: 'login_failed', entityType: 'authentication', summary: 'A sign-in attempt failed.' }); throw new ApiError(401, 'The email or password is incorrect.', 'INVALID_CREDENTIALS'); } const methods = mfaMethodsForUser(user); if (methods.required) { await establishPreMfaSession(req, user); await audit({ actorId: user.id, actorName: user.full_name, action: hasEnrolledMfa(user) ? 'password_verified_mfa_challenge' : 'password_verified_mfa_enrollment_required', entityType: 'authentication', entityId: user.id, summary: hasEnrolledMfa(user) ? 'Password accepted; MFA verification is required.' : 'Password accepted; initial MFA enrollment is required.' }); return res.json({ requiresMfa: true, enrollmentRequired: !hasEnrolledMfa(user), methods, user: safeUser(user), demoMode: !isProduction }); } await establishSession(req, user); await audit({ actorId: user.id, actorName: user.full_name, action: 'login_succeeded', entityType: 'authentication', entityId: user.id, summary: 'Signed in to the parish dashboard.' }); return res.json({ user: safeUser(user), demoMode: !isProduction }); } catch (error) { return next(error); } });
app.post('/api/auth/logout', requireAuth, async (req, res, next) => { const actor = req.user; req.session.destroy(async (error) => { if (error) return next(error); try { await audit({ actorId: actor.id, actorName: actor.fullName, action: 'logout', entityType: 'authentication', entityId: actor.id, summary: 'Signed out of the parish dashboard.' }); res.clearCookie('lwmp.sid'); return res.status(204).end(); } catch (auditError) { return next(auditError); } }); });
