app.get('/api/invitations/:token', async (req, res, next) => { try { const token = String(req.params.token || ''); if (token.length < 32) throw new ApiError(404, 'This staff invitation is not available.', 'INVITATION_NOT_FOUND'); const invitation = await findInvitation(token); if (!invitation) throw new ApiError(404, 'This staff invitation is invalid, expired, revoked, or already used.', 'INVITATION_NOT_FOUND'); return res.json({ invitation: publicInvitationDto(invitation) }); } catch (error) { return next(error); } });
app.post('/api/invitations/:token/accept', loginLimiter, async (req, res, next) => { try { const password = z.string().min(12).max(128).refine((value) => /[a-z]/.test(value) && /[A-Z]/.test(value) && /\d/.test(value)); const parsed = z.object({ password }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Choose a stronger password before creating your staff account.', 'WEAK_PASSWORD', parsed.error.issues); const user = await acceptStaffInvitation(String(req.params.token || ''), parsed.data.password); const rawUser = await getUserById(user.id); await establishPreMfaSession(req, rawUser); return res.status(201).json({ user, requiresMfa: true, enrollmentRequired: true, methods: mfaMethodsForUser(rawUser), message: 'Account created. Set up an authenticator app or passkey before entering the dashboard.' }); } catch (error) { return next(error); } });
app.get('/api/auth/mfa/status', requireMfaSetup, async (req, res, next) => { try { return res.json({ ...(await getMfaStatus(req.user.id)), preMfaChallenge: Boolean(req.session?.preMfaUserId) }); } catch (error) { return next(error); } });
app.post('/api/auth/mfa/totp/start', requireMfaSetup, async (req, res, next) => { try { return res.json({ enrollment: await beginTotpEnrollment(req.user._row) }); } catch (error) { return next(error); } });
app.post('/api/auth/mfa/totp/confirm', requireMfaSetup, mfaLimiter, async (req, res, next) => { try { const parsed = z.object({ code: z.string().trim().regex(/^\d{6}$/) }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Enter the six-digit code from your authenticator app.', 'INVALID_TOTP_CODE', parsed.error.issues); const result = await confirmTotpEnrollment(req.user._row, parsed.data.code); const refreshed = await getUserById(req.user.id); if (req.session?.preMfaUserId) await establishSession(req, refreshed); return res.json({ user: safeUser(refreshed), recoveryCodes: result.recoveryCodes, message: 'Authenticator app enrolled. Save the recovery codes somewhere safe now; they will not be shown again.' }); } catch (error) { return next(error); } });
app.post('/api/auth/mfa/verify', mfaLimiter, async (req, res, next) => { try { const user = await preMfaUser(req); if (!user) throw new ApiError(401, 'Your MFA challenge has expired. Sign in again.', 'MFA_CHALLENGE_EXPIRED'); const parsed = z.object({ method: z.enum(['totp','recovery']), code: z.string().trim().min(6).max(40) }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Enter your authenticator or recovery code.', 'INVALID_MFA_CODE', parsed.error.issues); const valid = parsed.data.method === 'totp' ? await verifyTotpCode(user, parsed.data.code) : await useRecoveryCode(user.id, parsed.data.code); if (!valid) { await audit({ actorId: user.id, actorName: user.full_name, action: 'mfa_verification_failed', entityType: 'authentication', entityId: user.id, summary: 'An MFA code verification failed.' }); throw new ApiError(401, 'That verification code is not valid.', 'INVALID_MFA_CODE'); } await establishSession(req, user); await audit({ actorId: user.id, actorName: user.full_name, action: 'mfa_verification_succeeded', entityType: 'authentication', entityId: user.id, summary: `Completed ${parsed.data.method === 'totp' ? 'authenticator' : 'recovery code'} MFA verification.` }); return res.json({ user: safeUser(user), demoMode: !isProduction }); } catch (error) { return next(error); } });
app.post('/api/auth/mfa/recovery-codes', requireAuth, mfaLimiter, async (req, res, next) => { try { const parsed = z.object({ code: z.string().trim().regex(/^\d{6}$/) }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Enter a current authenticator code.', 'INVALID_TOTP_CODE', parsed.error.issues); const recoveryCodes = await regenerateRecoveryCodes(req.user._row, parsed.data.code); return res.json({ recoveryCodes, message: 'New recovery codes have replaced all prior unused recovery codes.' }); } catch (error) { return next(error); } });
function saveRequestSession(req) { return new Promise<void>((resolve, reject) => req.session.save((error) => error ? reject(error) : resolve())); }
function validCeremony(ceremony) { return ceremony && new Date(ceremony.expiresAt).getTime() > Date.now(); }
function credentialForVerification(row) { return { id: row.credential_id, publicKey: new Uint8Array(Buffer.from(row.public_key, 'base64url')), counter: Number(row.counter || 0), transports: JSON.parse(row.transports || '[]') }; }
async function beginPasskeyAuthentication(req, user, key = 'passkeyAuthentication') { const credentials = await db.all('SELECT * FROM passkeys WHERE user_id = ? ORDER BY created_at ASC', user.id); if (!credentials.length) throw new ApiError(422, 'No passkey is enrolled for this account. Use your authenticator app instead.', 'PASSKEY_NOT_ENROLLED'); const { origin, rpID } = webAuthnConfiguration(req); const options = await generateAuthenticationOptions({ rpID, allowCredentials: credentials.map((credential) => ({ id: credential.credential_id, transports: JSON.parse(credential.transports || '[]') })), userVerification: 'required', timeout: 60000 }); req.session[key] = { challenge: options.challenge, userId: user.id, origin, rpID, expiresAt: new Date(Date.now() + 120000).toISOString() }; await saveRequestSession(req); return options; }
async function completePasskeyAuthentication(req, response, key = 'passkeyAuthentication') { const ceremony = req.session?.[key]; if (!validCeremony(ceremony)) throw new ApiError(401, 'This passkey request has expired. Start again.', 'PASSKEY_CHALLENGE_EXPIRED'); const user = await getUserById(ceremony.userId); if (!user) throw new ApiError(401, 'This staff account is no longer active.', 'AUTH_REQUIRED'); const passkey = await db.one('SELECT * FROM passkeys WHERE credential_id = ? AND user_id = ?', String(response?.id || ''), user.id); if (!passkey) throw new ApiError(401, 'This passkey is not recognised for the requested account.', 'PASSKEY_NOT_RECOGNISED'); let verification; try { verification = await verifyAuthenticationResponse({ response, expectedChallenge: ceremony.challenge, expectedOrigin: ceremony.origin, expectedRPID: ceremony.rpID, credential: credentialForVerification(passkey), requireUserVerification: true }); } catch { throw new ApiError(401, 'Passkey verification failed. Try again or use another sign-in method.', 'PASSKEY_VERIFICATION_FAILED'); } if (!verification.verified) throw new ApiError(401, 'Passkey verification failed. Try again.', 'PASSKEY_VERIFICATION_FAILED'); await db.run('UPDATE passkeys SET counter = ?, last_used_at = ? WHERE id = ?', verification.authenticationInfo.newCounter, nowIso(), passkey.id); return user; }
app.post('/api/auth/passkey/options', loginLimiter, async (req, res, next) => { try { const parsed = z.object({ email: z.string().email() }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Enter the email address associated with your passkey.', 'INVALID_LOGIN'); const user = await db.one('SELECT * FROM users WHERE email = ? AND active = TRUE', parsed.data.email.trim().toLowerCase()); if (!user) throw new ApiError(401, 'The requested passkey sign-in is not available.', 'PASSKEY_NOT_AVAILABLE'); return res.json({ options: await beginPasskeyAuthentication(req, user) }); } catch (error) { return next(error); } });
app.post('/api/auth/passkey/verify', loginLimiter, async (req, res, next) => { try { const user = await completePasskeyAuthentication(req, req.body?.response); await establishSession(req, user); await audit({ actorId: user.id, actorName: user.full_name, action: 'passkey_login_succeeded', entityType: 'authentication', entityId: user.id, summary: 'Signed in with a verified passkey.' }); return res.json({ user: safeUser(user), demoMode: !isProduction }); } catch (error) { return next(error); } });
app.post('/api/auth/mfa/passkey/options', requireMfaSetup, mfaLimiter, async (req, res, next) => { try { if (!req.session?.preMfaUserId) throw new ApiError(409, 'Start with password sign-in before using a passkey as your second factor.', 'MFA_CHALLENGE_REQUIRED'); return res.json({ options: await beginPasskeyAuthentication(req, req.user._row, 'passkeyMfaAuthentication') }); } catch (error) { return next(error); } });
app.post('/api/auth/mfa/passkey/verify', mfaLimiter, async (req, res, next) => { try { const user = await completePasskeyAuthentication(req, req.body?.response, 'passkeyMfaAuthentication'); if (req.session?.preMfaUserId !== user.id) throw new ApiError(401, 'This passkey challenge does not match the sign-in request.', 'PASSKEY_VERIFICATION_FAILED'); await establishSession(req, user); await audit({ actorId: user.id, actorName: user.full_name, action: 'passkey_mfa_succeeded', entityType: 'authentication', entityId: user.id, summary: 'Completed MFA with a verified passkey.' }); return res.json({ user: safeUser(user), demoMode: !isProduction }); } catch (error) { return next(error); } });
app.post('/api/auth/passkeys/registration/options', requireMfaSetup, async (req, res, next) => { try { const user = req.user._row; const credentials = await db.all('SELECT * FROM passkeys WHERE user_id = ? ORDER BY created_at ASC', user.id); const { origin, rpID } = webAuthnConfiguration(req); const options = await generateRegistrationOptions({ rpName: 'Living Water Mega Parish Birthday Care', rpID, userID: Buffer.from(user.id), userName: user.email, userDisplayName: user.full_name, attestationType: 'none', timeout: 60000, excludeCredentials: credentials.map((credential) => ({ id: credential.credential_id, transports: JSON.parse(credential.transports || '[]') })), authenticatorSelection: { residentKey: 'preferred', userVerification: 'required' } }); req.session.passkeyRegistration = { challenge: options.challenge, userId: user.id, origin, rpID, expiresAt: new Date(Date.now() + 120000).toISOString() }; await saveRequestSession(req); return res.json({ options }); } catch (error) { return next(error); } });
app.post('/api/auth/passkeys/registration/verify', requireMfaSetup, async (req, res, next) => { try { const ceremony = req.session?.passkeyRegistration; if (!validCeremony(ceremony) || ceremony.userId !== req.user.id) throw new ApiError(401, 'This passkey enrollment request has expired. Start again.', 'PASSKEY_CHALLENGE_EXPIRED'); let verification; try { verification = await verifyRegistrationResponse({ response: req.body?.response, expectedChallenge: ceremony.challenge, expectedOrigin: ceremony.origin, expectedRPID: ceremony.rpID, requireUserVerification: true }); } catch { throw new ApiError(422, 'Passkey enrollment could not be verified. Try again.', 'PASSKEY_VERIFICATION_FAILED'); } if (!verification.verified || !verification.registrationInfo) throw new ApiError(422, 'Passkey enrollment could not be verified. Try again.', 'PASSKEY_VERIFICATION_FAILED'); const info = verification.registrationInfo; const timestamp = nowIso(); const transports = Array.isArray(req.body?.response?.response?.transports) ? req.body.response.response.transports : []; try { await db.transaction(async (tx) => { await tx.run(`INSERT INTO passkeys (id, user_id, credential_id, public_key, counter, transports, device_type, backed_up, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`, newId('passkey_'), req.user.id, info.credential.id, Buffer.from(info.credential.publicKey).toString('base64url'), info.credential.counter, JSON.stringify(transports), info.credentialDeviceType, info.credentialBackedUp, timestamp); await tx.run(`UPDATE users SET passkey_enrolled_at = COALESCE(passkey_enrolled_at, ?), mfa_required = TRUE, mfa_state = 'passkey_enrolled', updated_at = ? WHERE id = ?`, timestamp, timestamp, req.user.id); }); } catch (error) { if (String(error.message || '').includes('unique')) throw new ApiError(409, 'This passkey is already registered to a staff account.', 'PASSKEY_ALREADY_REGISTERED'); throw error; } const user = await getUserById(req.user.id); if (req.session?.preMfaUserId) await establishSession(req, user); await audit({ actorId: user.id, actorName: user.full_name, action: 'passkey_enrollment_completed', entityType: 'authentication', entityId: user.id, summary: 'Enrolled a passkey for staff MFA.' }); return res.status(201).json({ user: safeUser(user), message: 'Passkey enrolled successfully. It can now be used for secure sign-in.' }); } catch (error) { return next(error); } });

app.get('/api/dashboard', requireAuth, async (req, res, next) => { try { return res.json(await dashboardFor(req.user)); } catch (error) { return next(error); } });
app.get('/api/members', requireAuth, requireRoles('owner','membership_officer'), async (req, res, next) => { try { const search = cleanString(req.query.search); const status = cleanString(req.query.status); const group = cleanString(req.query.group); const params = []; const where = []; if (search) { where.push(`(LOWER(first_name || ' ' || last_name) LIKE ? OR LOWER(member_code) LIKE ?)`); const pattern = `%${search.toLowerCase()}%`; params.push(pattern, pattern); } if (status && status !== 'all') { where.push('status = ?'); params.push(status); } if (group && group !== 'all') { where.push('ministry_group = ?'); params.push(group); } const clause = where.length ? `WHERE ${where.join(' AND ')}` : ''; const page = Math.max(1, Number(req.query.page) || 1); const pageSize = Math.min(100, Math.max(10, Number(req.query.pageSize) || 20)); const total = await db.one(`SELECT COUNT(*)::int AS count FROM members ${clause}`, ...params); const rows = await db.all(`SELECT * FROM members ${clause} ORDER BY updated_at DESC LIMIT ? OFFSET ?`, ...params, pageSize, (page - 1) * pageSize); const groups = await db.all('SELECT DISTINCT ministry_group AS name FROM members ORDER BY ministry_group'); return res.json({ items: rows.map((row) => makeMember(row, req.user)), total: Number(total.count), page, pageSize, groups: groups.map((item) => item.name) }); } catch (error) { return next(error); } });
