const ruleSchema = z.object({ enabled: z.boolean(), digestMode: z.literal('daily_digest'), alertTime: z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/), daysBefore: z.coerce.number().int().min(0).max(14), primaryChannel: z.enum(['whatsapp','sms']), smsFallback: z.boolean(), feb29Policy: z.enum(['feb28','mar1']) });
app.put('/api/settings/rule', requireAuth, requireRoles('owner'), async (req, res, next) => { try { const parsed = ruleSchema.safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Check the notification rule values.', 'INVALID_RULE', parsed.error.issues); const rule = await updateNotificationRule(parsed.data, req.user); return res.json({ rule: { id: rule.id, name: rule.name, enabled: Boolean(rule.enabled), digestMode: rule.digest_mode, alertTime: rule.alert_time, timezone: rule.timezone, daysBefore: Number(rule.days_before), primaryChannel: rule.primary_channel, smsFallback: Boolean(rule.sms_fallback), feb29Policy: rule.feb29_policy, updatedAt: rule.updated_at } }); } catch (error) { return next(error); } });

const endpointCreateSchema = z.object({ channel: z.enum(['whatsapp','sms']), phone: z.string().min(7).max(40), label: z.string().trim().min(2).max(80), priority: z.coerce.number().int().min(1).max(10).default(1), optInConfirmed: z.literal(true) });
function endpointCanBeManagedBy(endpoint, user) { return endpoint.user_id === user.id || user.role === 'owner'; }
async function requestEndpointVerification(endpoint, actor) { const phone = decryptValue(endpoint.phone_encrypted); if (!phone) throw new ApiError(422, 'This endpoint has no usable phone number.', 'ENDPOINT_PHONE_UNAVAILABLE'); const timestamp = nowIso(); const expiresAt = new Date(Date.now() + 600000).toISOString(); const code = String(crypto.randomInt(100000, 1000000)); const id = newId('endpoint_verify_'); await db.transaction(async (tx) => { await tx.run('DELETE FROM endpoint_verifications WHERE endpoint_id = ? AND consumed_at IS NULL', endpoint.id); await tx.run(`INSERT INTO endpoint_verifications (id, endpoint_id, code_hash, purpose, delivery_channel, provider, provider_message_id, requested_at, expires_at, attempts) VALUES (?, ?, ?, 'endpoint_ownership', 'sms', NULL, NULL, ?, ?, 0)`, id, endpoint.id, lookupHash(`endpoint-verification:${endpoint.id}:${code}`), timestamp, expiresAt); }); try { const delivery = await sendEndpointVerificationSms(phone, code); await db.run('UPDATE endpoint_verifications SET provider = ?, provider_message_id = ? WHERE id = ?', delivery.provider || null, delivery.providerMessageId || null, id); await audit({ actorId: actor.id, actorName: actor.fullName, action: 'endpoint_verification_requested', entityType: 'admin_endpoint', entityId: endpoint.id, summary: `Sent an SMS ownership verification challenge for a ${endpoint.channel} endpoint.`, metadata: { provider: delivery.provider, channel: endpoint.channel } }); return { expiresAt, deliveryMode: process.env.MESSAGE_MODE || 'mock', debugCode: !isProduction && (process.env.MESSAGE_MODE || 'mock') === 'mock' ? code : undefined }; } catch (error) { await db.run('DELETE FROM endpoint_verifications WHERE id = ?', id); throw new ApiError(503, `Could not send the verification SMS. ${error.message || ''}`.trim(), 'ENDPOINT_VERIFICATION_SEND_FAILED'); } }
app.post('/api/endpoints', requireAuth, requireRoles('owner','membership_officer','birthday_coordinator'), endpointVerificationLimiter, async (req, res, next) => { try { const parsed = endpointCreateSchema.safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Enter a valid notification endpoint and record its opt-in.', 'INVALID_ENDPOINT', parsed.error.issues); const data = parsed.data; const phone = normalizePhone(data.phone); const timestamp = nowIso(); const id = newId('endpoint_'); await db.run(`INSERT INTO admin_endpoints (id, user_id, channel, phone_encrypted, phone_hash, label, priority, enabled, verified_at, opted_in_at, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, TRUE, NULL, ?, ?, ?)`, id, req.user.id, data.channel, encryptValue(phone), lookupHash(phone), data.label, data.priority, timestamp, timestamp, timestamp); const endpoint = await db.one('SELECT * FROM admin_endpoints WHERE id = ?', id); await audit({ actorId: req.user.id, actorName: req.user.fullName, action: 'admin_endpoint_added', entityType: 'admin_endpoint', entityId: id, summary: `Added a ${data.channel} notification endpoint awaiting ownership verification.`, metadata: { optInRecordedAt: timestamp } }); const verification = await requestEndpointVerification(endpoint, req.user); return res.status(201).json({ endpoint: endpointDto(endpoint, { revealPhone: true }), verification, message: 'Consent was recorded. Enter the SMS code to prove the number is controlled before alerts can be sent.' }); } catch (error) { return next(error); } });
app.post('/api/endpoints/:id/verification/resend', requireAuth, requireRoles('owner','membership_officer','birthday_coordinator'), endpointVerificationLimiter, async (req, res, next) => { try { const endpoint = await db.one('SELECT * FROM admin_endpoints WHERE id = ?', req.params.id); if (!endpoint) throw new ApiError(404, 'Notification endpoint not found.', 'ENDPOINT_NOT_FOUND'); if (!endpointCanBeManagedBy(endpoint, req.user)) throw new ApiError(403, 'You can only verify your own notification endpoints.', 'FORBIDDEN'); if (endpoint.verified_at) throw new ApiError(409, 'This endpoint is already verified.', 'ENDPOINT_ALREADY_VERIFIED'); return res.json({ verification: await requestEndpointVerification(endpoint, req.user), message: 'A fresh verification code was sent by SMS.' }); } catch (error) { return next(error); } });
app.post('/api/endpoints/:id/verification/confirm', requireAuth, requireRoles('owner','membership_officer','birthday_coordinator'), mfaLimiter, async (req, res, next) => { try { const endpoint = await db.one('SELECT * FROM admin_endpoints WHERE id = ?', req.params.id); if (!endpoint) throw new ApiError(404, 'Notification endpoint not found.', 'ENDPOINT_NOT_FOUND'); if (!endpointCanBeManagedBy(endpoint, req.user)) throw new ApiError(403, 'You can only verify your own notification endpoints.', 'FORBIDDEN'); if (endpoint.verified_at) return res.json({ endpoint: endpointDto(endpoint, { revealPhone: true }), message: 'This endpoint is already verified.' }); const parsed = z.object({ code: z.string().trim().regex(/^\d{6}$/) }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Enter the six-digit SMS verification code.', 'INVALID_ENDPOINT_CODE', parsed.error.issues); const verification = await db.one(`SELECT * FROM endpoint_verifications WHERE endpoint_id = ? AND consumed_at IS NULL ORDER BY requested_at DESC LIMIT 1`, endpoint.id); if (!verification || new Date(verification.expires_at).getTime() < Date.now()) throw new ApiError(410, 'This code has expired. Request a new verification code.', 'ENDPOINT_CODE_EXPIRED'); if (Number(verification.attempts) >= 5) throw new ApiError(429, 'Too many attempts for this code. Request a fresh verification code.', 'ENDPOINT_CODE_LOCKED'); await db.run('UPDATE endpoint_verifications SET attempts = attempts + 1 WHERE id = ?', verification.id); const codeMatches = verification.provider === 'termii_otp' ? await verifyTermiiOtp(verification.provider_message_id, parsed.data.code) : crypto.timingSafeEqual(Buffer.from(lookupHash(`endpoint-verification:${endpoint.id}:${parsed.data.code}`)), Buffer.from(verification.code_hash)); if (!codeMatches) throw new ApiError(401, 'That verification code is not correct.', 'INVALID_ENDPOINT_CODE'); const timestamp = nowIso(); await db.transaction(async (tx) => { await tx.run('UPDATE endpoint_verifications SET consumed_at = ? WHERE id = ?', timestamp, verification.id); await tx.run('UPDATE admin_endpoints SET verified_at = ?, updated_at = ? WHERE id = ?', timestamp, timestamp, endpoint.id); }); const verifiedEndpoint = await db.one('SELECT * FROM admin_endpoints WHERE id = ?', endpoint.id); await audit({ actorId: req.user.id, actorName: req.user.fullName, action: 'endpoint_ownership_verified', entityType: 'admin_endpoint', entityId: endpoint.id, summary: `Verified ownership of a ${endpoint.channel} notification endpoint.`, metadata: { consentRecordedAt: endpoint.opted_in_at } }); return res.json({ endpoint: endpointDto(verifiedEndpoint, { revealPhone: true }), message: 'Endpoint verified. It is now eligible for the parish notification rule.' }); } catch (error) { return next(error); } });
app.patch('/api/endpoints/:id', requireAuth, requireRoles('owner','membership_officer','birthday_coordinator'), async (req, res, next) => { try { const endpoint = await db.one('SELECT * FROM admin_endpoints WHERE id = ?', req.params.id); if (!endpoint) throw new ApiError(404, 'Notification endpoint not found.', 'ENDPOINT_NOT_FOUND'); if (!endpointCanBeManagedBy(endpoint, req.user)) throw new ApiError(403, 'You can only update your own notification endpoints.', 'FORBIDDEN'); const parsed = z.object({ enabled: z.boolean().optional(), priority: z.coerce.number().int().min(1).max(10).optional() }).safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Check the endpoint settings.', 'INVALID_ENDPOINT', parsed.error.issues); if (parsed.data.enabled === true && !endpoint.verified_at) throw new ApiError(409, 'Verify the endpoint before enabling it.', 'ENDPOINT_VERIFICATION_REQUIRED'); await db.run(`UPDATE admin_endpoints SET enabled = COALESCE(?, enabled), priority = COALESCE(?, priority), updated_at = ? WHERE id = ?`, typeof parsed.data.enabled === 'boolean' ? parsed.data.enabled : null, parsed.data.priority ?? null, nowIso(), endpoint.id); await audit({ actorId: req.user.id, actorName: req.user.fullName, action: 'admin_endpoint_updated', entityType: 'admin_endpoint', entityId: endpoint.id, summary: 'Updated notification endpoint preferences.' }); return res.json({ endpoint: endpointDto(await db.one('SELECT * FROM admin_endpoints WHERE id = ?', endpoint.id), { revealPhone: true }) }); } catch (error) { return next(error); } });

const staffInvitationSchema = z.object({ fullName: z.string().trim().min(3).max(120), email: z.string().trim().email(), role: z.enum(['owner','membership_officer','birthday_coordinator','auditor']), groupScope: z.array(z.string().trim().min(2).max(80)).max(30).default([]) });
app.get('/api/staff/access', requireAuth, requireRoles('owner'), async (req, res, next) => { try { return res.json(await listStaffAccess()); } catch (error) { return next(error); } });
app.post('/api/staff/invitations', requireAuth, requireRoles('owner'), async (req, res, next) => { try { const parsed = staffInvitationSchema.safeParse(req.body); if (!parsed.success) throw new ApiError(422, 'Check the staff invitation details.', 'INVALID_STAFF_INVITATION', parsed.error.issues); const result = await createStaffInvitation({ ...parsed.data, groupScope: [...new Set(parsed.data.groupScope)] }, req.user, applicationBaseUrl(req)); return res.status(201).json({ ...result, message: result.delivery.status === 'delivered' ? 'Staff invitation created and email delivery was accepted.' : 'Staff invitation was created, but email delivery failed. Check the configured email provider before inviting again.' }); } catch (error) { return next(error); } });
app.post('/api/staff/invitations/:id/revoke', requireAuth, requireRoles('owner'), async (req, res, next) => { try { await revokeInvitation(req.params.id, req.user); return res.status(204).end(); } catch (error) { return next(error); } });
app.post('/api/staff/:id/deactivate', requireAuth, requireRoles('owner'), async (req, res, next) => { try { await deactivateStaffAccount(req.params.id, req.user); return res.status(204).end(); } catch (error) { return next(error); } });
app.post('/api/imports/preview', requireAuth, requireRoles('owner','membership_officer'), async (req, res, next) => { try { const rows = await parseImportRows(req.body?.csvText); return res.json({ rows, summary: { total: rows.length, ready: rows.filter((row) => row.valid && !row.duplicate).length, invalid: rows.filter((row) => !row.valid).length, duplicates: rows.filter((row) => row.duplicate).length } }); } catch (error) { return next(error); } });
app.post('/api/imports/commit', requireAuth, requireRoles('owner','membership_officer'), async (req, res, next) => { try { const rows = Array.isArray(req.body?.rows) ? req.body.rows : []; if (!rows.length || rows.length > 500) throw new ApiError(422, 'Select between 1 and 500 validated rows to import.', 'INVALID_IMPORT_COMMIT'); let imported = 0; const rejected = []; for (const item of rows) { if (!item?.valid || item?.duplicate) { rejected.push({ rowNumber: item?.rowNumber, reason: 'Row is invalid or a duplicate candidate.' }); continue; } try { await createMember(parseMemberPayload({ ...item, consentRecorded: true, confirmPotentialDuplicate: false }, { requireConsent: true }), req.user, { source: 'Reviewed CSV import' }); imported += 1; } catch (error) { rejected.push({ rowNumber: item?.rowNumber, reason: error.message }); } } await audit({ actorId: req.user.id, actorName: req.user.fullName, action: 'members_imported', entityType: 'import', summary: `Committed reviewed CSV import: ${imported} member(s) created, ${rejected.length} skipped.`, metadata: { imported, rejected: rejected.length } }); return res.status(201).json({ imported, rejected, message: `${imported} member record(s) imported. No raw CSV was retained by the server.` }); } catch (error) { return next(error); } });
app.get('/api/audit', requireAuth, requireRoles('owner','auditor'), async (req, res, next) => { try { const limit = Math.min(150, Math.max(10, Number(req.query.limit) || 80)); const rows = await db.all(`SELECT * FROM audit_events ORDER BY created_at DESC LIMIT ?`, limit); return res.json({ items: rows.map((row) => ({ id: row.id, actorName: row.actor_name, action: row.action, entityType: row.entity_type, entityId: row.entity_id, summary: row.summary, createdAt: row.created_at })) }); } catch (error) { return next(error); } });

app.get('/api/webhooks/whatsapp', (req, res) => req.query['hub.mode'] === 'subscribe' && req.query['hub.verify_token'] === WEBHOOK_VERIFY_TOKEN ? res.status(200).send(req.query['hub.challenge']) : res.sendStatus(403));
app.post('/api/webhooks/whatsapp', async (req, res, next) => { try { if (!verifyMetaSignature(req)) throw new ApiError(401, 'Webhook signature verification failed.', 'INVALID_WEBHOOK_SIGNATURE'); const statuses = req.body?.entry?.flatMap((entry) => entry.changes || []).flatMap((change) => change?.value?.statuses || []) || []; for (const status of statuses) await applyProviderStatus({ provider: 'meta', providerMessageId: status.id, status: status.status, eventHash: crypto.createHash('sha256').update(JSON.stringify(status)).digest('hex'), eventType: 'whatsapp_status' }); return res.sendStatus(200); } catch (error) { return next(error); } });
app.post('/api/webhooks/sms', async (req, res, next) => { try { if (!verifyTermiiSignature(req)) throw new ApiError(401, 'Termii webhook signature verification failed.', 'INVALID_WEBHOOK_SIGNATURE'); const rawStatus = String(req.body?.status || '').toLowerCase(); const status = rawStatus.includes('deliver') ? 'delivered' : /fail|dnd|reject|expired/.test(rawStatus) ? 'failed' : rawStatus.includes('sent') ? 'sent' : 'provider_accepted'; await applyProviderStatus({ provider: 'termii', providerMessageId: req.body?.message_id || req.body?.message_id_str || req.body?.id, status, eventHash: crypto.createHash('sha256').update(req.rawBody || Buffer.from(JSON.stringify(req.body))).digest('hex'), eventType: 'sms_delivery_report' }); return res.sendStatus(200); } catch (error) { return next(error); } });

app.use('/api', (req, res, next) => next(new ApiError(404, 'API endpoint not found.', 'API_NOT_FOUND')));
if (fs.existsSync(distDirectory)) { app.use(express.static(distDirectory, { index: false, maxAge: isProduction ? '1h' : 0 })); app.get('/{*splat}', (req, res) => res.sendFile(path.join(distDirectory, 'index.html'))); } else app.get('/{*splat}', (req, res) => res.status(503).send('Frontend has not been built. Run npm run build first.'));
app.use((error, req, res, next) => { const status = error instanceof ApiError ? error.status : 500; const code = error instanceof ApiError ? error.code : 'INTERNAL_ERROR'; const message = error instanceof ApiError ? error.message : 'An unexpected error occurred.'; if (!(error instanceof ApiError)) console.error(error); return req.path.startsWith('/api/') ? res.status(status).json({ error: { code, message, details: error instanceof ApiError ? error.details : undefined } }) : res.status(status).send(message); });
function lagosClock() { const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Lagos', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date()); const get = (type) => parts.find((part) => part.type === type)?.value; return `${get('hour')}:${get('minute')}`; }
let lastRunMinute = null; async function scheduledTick() { try { const rule = await getNotificationRuleDto(); const nowMinute = lagosClock(); const key = `${toIsoDate(lagosDateParts())}:${nowMinute}`; if (rule?.enabled && rule.alertTime === nowMinute && lastRunMinute !== key) { lastRunMinute = key; await runBirthdayNotifications(); } await processOutboxJobs(); } catch (error) { console.error('Scheduled worker error', error); } }
if (process.env.SCHEDULER_ENABLED === 'true') cron.schedule('* * * * *', scheduledTick, { timezone: 'Africa/Lagos' });
app.listen(port, host, () => console.log(`Living Water PostgreSQL runtime listening on http://${host}:${port}; scheduler ${process.env.SCHEDULER_ENABLED === 'true' ? 'enabled' : 'external'}.`));
